import re
from typing import Any, Dict, Tuple


class K8sValidator:
    """
    Kubernetes template validator with strict name validation that allows
    double-curly braces templating blocks (e.g., {{ .Release.Name }}) while
    enforcing DNS-1123 subdomain rules on the non-templated portions.
    """

    # DNS-1123 subdomain regex: start/end alphanumeric, allow '-', '.' in between
    _dns1123_re = re.compile(r"^[a-z0-9]([-a-z0-9.]*[a-z0-9])?$")
    # Match double-curly-brace templating blocks lazily, allow newlines
    _double_curly_block_re = re.compile(r"\{\{.*?\}\}", re.DOTALL)

    @staticmethod
    def is_valid_template(template: Any) -> Tuple[bool, str]:
        is_valid = isinstance(template, dict)
        if not is_valid:
            return is_valid, f'template is not a dict, but {type(template)}'

        is_valid, reason = K8sValidator._has_required_fields(template)
        if not is_valid:
            return is_valid, reason

        is_valid, reason = K8sValidator._is_section_valid(template)
        if not is_valid:
            return is_valid, reason

        return True, ''

    @staticmethod
    def _has_required_fields(template: Dict[str, Any]) -> Tuple[bool, str]:
        for key in ['apiVersion', 'kind']:
            if key not in template.keys():
                return False, f'the key {key} does not exist in template structure'
        return True, ''

    @staticmethod
    def _is_section_valid(template: Dict[str, Any]) -> Tuple[bool, str]:
        for segment in template.keys():
            if isinstance(template[segment], dict):
                is_section_valid, reason = K8sValidator._is_section_valid(template[segment])
                if not is_section_valid:
                    return is_section_valid, reason
            elif isinstance(template[segment], list):
                for entry in template[segment]:
                    if isinstance(entry, dict):
                        is_section_valid, reason = K8sValidator._is_section_valid(entry)
                        if not is_section_valid:
                            return is_section_valid, reason
            elif segment == 'name':
                is_section_valid, reason = K8sValidator._is_name_valid(template[segment])
                if not is_section_valid:
                    return is_section_valid, reason
        return True, ''

    @staticmethod
    def is_valid_name(name: Any) -> Tuple[bool, str]:
        """
        Public helper to validate Kubernetes names with support for double-curly braces templating.
        """
        return K8sValidator._is_name_valid(name)

    @staticmethod
    def _is_name_valid(name: Any) -> Tuple[bool, str]:
        """
        Validate a Kubernetes resource/name-like string.

        - Accept double-curly braces templating blocks by sanitizing them to a safe token
        - Enforce DNS-1123 subdomain constraints on the sanitized result
        - Reject names with stray single braces outside templating blocks
        - Enforce max length of 253 characters
        """
        # Basic type/length guard
        if not isinstance(name, str) or len(name) > 253:
            return False, f'name {name} is invalid'

        original = name
        # Replace all {{ ... }} blocks with a safe alphanumeric placeholder
        sanitized = K8sValidator._double_curly_block_re.sub('x', original)

        # If any braces remain, they are stray single braces -> reject
        if '{' in sanitized or '}' in sanitized:
            return False, f'name {name} is invalid'

        # Enforce DNS-1123 subdomain pattern on sanitized name
        if not K8sValidator._dns1123_re.match(sanitized):
            return False, f'name {name} is invalid'

        return True, ''

